// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address referrer, address newUser, uint256 seedAmount) public {
        vm.assume(referrer != address(0) && referrer != newUser);
        vm.assume(seedAmount > 0 && seedAmount < 1e30);

        // Seed the market
        vm.prank(c.ceoAddress());
        c.seedMarket(1);

        // Give some drugs to referrer (by buying)
        vm.deal(referrer, 1 ether);
        vm.prank(referrer);
        c.buyDrugs{value: 1 ether}();

        uint256 referrerDrugsBefore = c.claimedDrugs(referrer);
        vm.assume(referrerDrugsBefore > 0);

        // newUser collects with referrer as referral, triggering the referrer bonus
        vm.prank(newUser);
        c.collectDrugs(referrer);

        // The rule: referrer's claimedDrugs should NOT be less than they were before
        assertTrue(c.claimedDrugs(referrer) >= referrerDrugsBefore);
    }
}

